   [169]={next_id=170, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是教皇大人和前任代理骑士长戴妮卡筹备了数十年，我们不过是循着她们铺好的路前行罢了。", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [170]={next_id=171, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她们是什么样的人？", msg_color="", msg_size=0, talker="艾丽西亚", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7166", 0, 0, 47, 166.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [171]={next_id=172, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她们……", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [172]={next_id=173, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蒂雅目光远眺，凝视着倒悬之塔下的滚滚黑云。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [173]={next_id=174, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="是愿意为守护的信念，把性命化作最后一道光的殉道者。", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [174]={next_id=175, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="至于她们的故事……说来话长，等维拉提亚重归安宁后，我会宴请各位来阿斯特利亚家里，好好和你们道来。", msg_color="", msg_size=0, talker="蒂雅", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4509", 0, 0, 3, 215.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [175]={next_id=176, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="艾丽西亚望着她被风吹动的银发，突然明白了莱斯坦斯支援的时机为何如此精准 —— 那些看似偶然的巧合，实则是两代人用信念编织的网。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [176]={next_id=177, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="艾丽西亚默然颔首，朝晖仍有些不放心地问道。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [177]={next_id=178, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="一个人？这对天兆之星来说岂不是自己送上门来了？", msg_color="", msg_size=0, talker="朝晖", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4520", 0, 0, 34, 220}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [178]={next_id=179, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="哎呀，小阿戴妮，可不要小看我哦，到底是谁送上门还说不定呢~", msg_color="", msg_size=0, talker="魁霎", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4510_1", 0, 0, 40.5, 185}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [179]={next_id=180, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="魁霎扬了扬手中的玩偶，将它抛了出去。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [180]={next_id=181, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="轰——！伴随沉闷的落地声，玩偶再度巨大化，将魁霎带到肩膀上。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [181]={next_id=182, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……唔哦！还有这种奇特的星源共鸣吗？", msg_color="", msg_size=0, talker="矢车菊", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "2504", 0, 0, -19, 208}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [182]={next_id=183, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="说是星源共鸣，但这上面的虚粒子波动依然剧烈，更像是和源能结合以后的能力。", msg_color="", msg_size=0, talker="烁曦", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4106", 0, 0, 49, 186}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [183]={next_id=184, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="妾身以为，更像是赋予人性以后的结果呢。", msg_color="", msg_size=0, talker="红叶", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4523", 0, 0, 120, 146.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
