   [189]={next_id=190, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="倒悬之塔的尖顶裂开蛛网般的缝隙，虚粒子凝成的黑潮如瀑布般，沿着塔身奔涌而下。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [190]={next_id=191, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="其中一股黑潮泼洒在众人面前，凝成了三个散发着强大虚粒子波动的高大身影。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [191]={next_id=192, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="古老的黑色铠甲覆在它们的身上，随着它们挥动武器而铿锵作响。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/cg/cg_11_104.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
